// shortcuts.json -> crates/shortcuts/src/generated.rs (pure; the build script writes the file).
import { type KeySet, type Platform, parseSequence, SCOPES, type ShortcutDef } from "./index.ts";

export const GENERATED_HEADER =
  "Generated by packages/shortcuts/scripts/build.ts from packages/shortcuts/shortcuts.json. Do not edit.";

const ID_RE = /^[a-z][A-Za-z0-9]*(\.[a-z][A-Za-z0-9]*)*$/;

/** Throws on duplicate ids, unknown scopes or unparsable keys. */
export function validateShortcuts(defs: readonly ShortcutDef[]): void {
  const seen = new Set<string>();
  for (const s of defs) {
    if (!ID_RE.test(s.id)) throw new Error(`shortcuts.json: bad id "${s.id}"`);
    if (seen.has(s.id)) throw new Error(`shortcuts.json: duplicate id "${s.id}"`);
    seen.add(s.id);
    if (!s.label?.trim()) throw new Error(`shortcuts.json: ${s.id} has no label`);
    if (!(SCOPES as readonly string[]).includes(s.scope))
      throw new Error(`shortcuts.json: ${s.id} has bad scope`);
    if (typeof s.palette !== "boolean") throw new Error(`shortcuts.json: ${s.id}.palette must be boolean`);
    if (
      s.keywords !== undefined &&
      (!Array.isArray(s.keywords) || s.keywords.some((k) => typeof k !== "string" || !k.trim()))
    )
      throw new Error(`shortcuts.json: ${s.id}.keywords must be non-empty strings`);
    for (const set of [s.keys, s.gmail]) {
      if (!set) continue;
      if (!Array.isArray(set.default)) throw new Error(`shortcuts.json: ${s.id} needs keys.default`);
      for (const k of [...set.default, ...(set.mac ?? []), ...(set.windows ?? []), ...(set.linux ?? [])]) {
        try {
          parseSequence(k);
        } catch (e) {
          throw new Error(`shortcuts.json: ${s.id}: ${(e as Error).message}`);
        }
      }
    }
    if (!s.palette && s.keys.default.length === 0 && !s.keys.mac?.length) {
      throw new Error(`shortcuts.json: ${s.id} is unreachable (no keys and not in the palette)`);
    }
  }
}

/** "thread.replyAll" -> "THREAD_REPLY_ALL" */
export function rustConstName(id: string): string {
  return id
    .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
    .replace(/\./g, "_")
    .toUpperCase();
}

/** "cmd+shift+l" -> "cmd-shift-l"; "g i" stays "g i"; "#" -> "#". GPUI keystroke syntax. */
export function toGpuiKeystrokes(keys: string): string {
  return parseSequence(keys)
    .map((c) => [...(["ctrl", "alt", "shift", "cmd"] as const).filter((m) => c[m]), c.key].join("-"))
    .join(" ");
}

const str = (s: string) => JSON.stringify(s);
const scopeVariant = (s: string) => s[0]!.toUpperCase() + s.slice(1);

function keyList(set: KeySet, p: Platform, gpui: boolean): string {
  const keys = set[p] ?? set.default;
  return `&[${keys.map((k) => str(gpui ? toGpuiKeystrokes(k) : k)).join(", ")}]`;
}

function keysLiteral(set: KeySet, indent: string): string {
  const fields = (["mac", "windows", "linux"] as const).map(
    (p) => `${indent}    ${p}: ${keyList(set, p, false)},`,
  );
  const gpui = (["mac", "windows", "linux"] as const).map(
    (p) => `${indent}    gpui_${p}: ${keyList(set, p, true)},`,
  );
  return `Keys {\n${[...fields, ...gpui].join("\n")}\n${indent}}`;
}

export function toRust(defs: readonly ShortcutDef[], version: number): string {
  validateShortcuts(defs);
  const entries = defs
    .map(
      (s) => `    Shortcut {
        id: ${str(s.id)},
        label: ${str(s.label)},
        group: ${str(s.group)},
        scope: Scope::${scopeVariant(s.scope)},
        palette: ${s.palette},
        keywords: &[${(s.keywords ?? []).map(str).join(", ")}],
        keys: ${keysLiteral(s.keys, "        ")},
        gmail: ${s.gmail ? `Some(${keysLiteral(s.gmail, "        ")})` : "None"},
    },`,
    )
    .join("\n");
  const ids = defs.map((s) => `    pub const ${rustConstName(s.id)}: &str = ${str(s.id)};`).join("\n");

  return `// ${GENERATED_HEADER}
// Rust owner: include with \`mod generated; pub use generated::*;\` in crates/shortcuts/src/lib.rs.
// Key notation is documented in packages/shortcuts/shortcuts.json. The gpui_* lists carry the same
// bindings in GPUI keystroke syntax ("cmd-k", "g i").
#![allow(dead_code)]

pub const VERSION: u32 = ${version};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Scope {
${SCOPES.map((s) => `    ${scopeVariant(s)},`).join("\n")}
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Platform {
    Mac,
    Windows,
    Linux,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Keymap {
    Superhuman,
    Gmail,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Keys {
    pub mac: &'static [&'static str],
    pub windows: &'static [&'static str],
    pub linux: &'static [&'static str],
    pub gpui_mac: &'static [&'static str],
    pub gpui_windows: &'static [&'static str],
    pub gpui_linux: &'static [&'static str],
}

impl Keys {
    pub const fn for_platform(&self, platform: Platform) -> &'static [&'static str] {
        match platform {
            Platform::Mac => self.mac,
            Platform::Windows => self.windows,
            Platform::Linux => self.linux,
        }
    }
    pub const fn gpui_for_platform(&self, platform: Platform) -> &'static [&'static str] {
        match platform {
            Platform::Mac => self.gpui_mac,
            Platform::Windows => self.gpui_windows,
            Platform::Linux => self.gpui_linux,
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Shortcut {
    pub id: &'static str,
    pub label: &'static str,
    pub group: &'static str,
    pub scope: Scope,
    /// Listed in the command palette.
    pub palette: bool,
    /// Extra words the command palette matches (synonyms).
    pub keywords: &'static [&'static str],
    pub keys: Keys,
    /// Overrides for the Gmail-style keymap.
    pub gmail: Option<Keys>,
}

impl Shortcut {
    pub const fn keys_for(&self, keymap: Keymap) -> &Keys {
        match (keymap, &self.gmail) {
            (Keymap::Gmail, Some(k)) => k,
            _ => &self.keys,
        }
    }
}

pub const SHORTCUTS: &[Shortcut] = &[
${entries}
];

pub fn find(id: &str) -> Option<&'static Shortcut> {
    SHORTCUTS.iter().find(|s| s.id == id)
}

/// Shortcut ids as constants, so Rust code never spells an id by hand.
pub mod ids {
${ids}
}
`;
}
